import{_ as i,a8 as d,o as s,c,au as p,a as u,a3 as o,K as l,L as t}from"./chunks/framework.DvmO9e3U.js";import"./chunks/theme.B5GsD1ii.js";const k=JSON.parse('{"title":"Claude Code 把记忆当数据库建索引，然后拼命劝模型少写","description":"","frontmatter":{"title":"Claude Code 把记忆当数据库建索引，然后拼命劝模型少写","abstract":"Claude Code 的记忆不是\\"记得多\\"，而是 MEMORY.md 只留一个 200 行以内的索引，细节全拆成主题文件。真正的关键在于写入端明确排除两类内容，否则索引一定会溢出。","created":"2026-11-09T00:00:00.000Z","updated":"2026-11-10T00:00:00.000Z","type":"调研","tags":["AI","Claude Code","Agent","记忆系统"],"category":["🧩 AI框架与Agent","AI 应用核心范式"]},"headers":[],"relativePath":"vault/Knowledge/AI/Claude Code 的记忆系统.md","filePath":"vault/Knowledge/AI/Claude Code 的记忆系统.md","lastUpdated":1794320166000}'),m={name:"vault/Knowledge/AI/Claude Code 的记忆系统.md"};function g(C,e,h,b,A,f){const a=d("VPNolebaseInlineLinkPreview"),r=d("NolebaseGitContributors"),n=d("NolebaseGitChangelog");return s(),c("div",null,[e[7]||(e[7]=p('<h1 id="claude-code-把记忆当数据库建索引-然后拼命劝模型少写" tabindex="-1">Claude Code 把记忆当数据库建索引，然后拼命劝模型少写 <a class="header-anchor" href="#claude-code-把记忆当数据库建索引-然后拼命劝模型少写" aria-label="Permalink to “Claude Code 把记忆当数据库建索引，然后拼命劝模型少写”">​</a></h1><p>第一次看到 Claude Code 的记忆设计，我的反应是&quot;这明明是个数据库&quot;：常驻一个索引，细节散在数据页里，需要时才读。</p><p>但再往下看会发现，重点不在索引结构，而在<strong>写入端的减法</strong>。索引之所以能长期不溢出，不是因为压缩算法好，是因为官方明确规定了什么不能写。</p><h2 id="一、两套系统-性质相反" tabindex="-1">一、两套系统，性质相反 <a class="header-anchor" href="#一、两套系统-性质相反" aria-label="Permalink to “一、两套系统，性质相反”">​</a></h2><p><code>CLAUDE.md</code> 和 auto memory 是两套东西：</p><ul><li><code>CLAUDE.md</code> <strong>由人写</strong>，放指令。</li><li>auto memory <strong>由 Claude 写</strong>，放它学到的东西。</li></ul><p>两者每次会话都会加载，但都<strong>只是上下文，不是强制配置</strong>。</p><p>这个区别很重要：官方明确说 <code>CLAUDE.md</code> 作为 user message 放在 system prompt 之后，<strong>不保证模型严格遵从</strong>。想让规则变成硬约束，得用 hook 来拦截。</p><p>很多人以为写了 <code>CLAUDE.md</code> 就能约束住行为，实际上它更像一份&quot;强烈建议&quot;。</p><h2 id="二、加载是拼接-不是覆盖" tabindex="-1">二、加载是拼接，不是覆盖 <a class="header-anchor" href="#二、加载是拼接-不是覆盖" aria-label="Permalink to “二、加载是拼接，不是覆盖”">​</a></h2><p><code>CLAUDE.md</code> 分四级作用域：</p><ol><li>managed policy</li><li>用户级 <code>~/.claude/CLAUDE.md</code></li><li>项目级 <code>./CLAUDE.md</code> 或 <code>./.claude/CLAUDE.md</code></li><li>本地 <code>./CLAUDE.local.md</code></li></ol><p>加载方式是从文件系统根逐级拼接到 cwd，<strong>不是覆盖</strong>。同一层里，<code>CLAUDE.local.md</code> 排在 <code>CLAUDE.md</code> 之后。</p><p>效果仍然是&quot;越具体越优先&quot;，但机制上是所有文件叠在一起，后出现的在上文里更靠后。</p><p>子目录的 <code>CLAUDE.md</code> 在启动时<strong>不加载</strong>，只有当 Claude 读、写、编辑该子目录的文件时才加载。这是为大仓库做的优化，避免一次性灌满上下文。</p><p>还有 <code>@path</code> 递归导入，最多 4 跳，代码块里的 <code>@</code> 不算——这个细节说明他们考虑过误触发。</p><h2 id="三、索引与数据分离" tabindex="-1">三、索引与数据分离 <a class="header-anchor" href="#三、索引与数据分离" aria-label="Permalink to “三、索引与数据分离”">​</a></h2><p>auto memory 放在 <code>~/.claude/projects/&lt;project&gt;/memory/</code>，按 git 仓库派生，<strong>同一个仓库的所有 worktree 共享</strong>。</p><p>记忆分四类，写在 frontmatter 的 <code>type</code> 里：<code>user</code>、<code>feedback</code>、<code>project</code>、<code>reference</code>。</p><p>体量控制是核心设计：</p><ul><li>启动时只读 <code>MEMORY.md</code> 的前 <strong>200 行或 25 KB</strong>，先到者为准。</li><li>其余每条记忆拆成<strong>独立主题文件</strong>，模型需要时自己打开。</li><li>接近上限时提醒压缩。</li><li>超限写入<strong>仍然成功</strong>，但下次加载会被截断。</li></ul><p>最后一条很关键：它不会阻止你写，只会让你写了看不到。这是一种&quot;软失败&quot;，比直接报错更隐蔽。</p><p>另外，写记忆文件时会在 frontmatter 记 <code>modified</code>（ISO 8601），供判断新旧。没有时间戳的记忆系统，迟早会被过期信息拖垮。</p><h2 id="四、写入端的两条排除规则" tabindex="-1">四、写入端的两条排除规则 <a class="header-anchor" href="#四、写入端的两条排除规则" aria-label="Permalink to “四、写入端的两条排除规则”">​</a></h2><p>这是我认为最值得抄的部分。</p><p>官方明确排除两类内容：</p><ol><li><strong>能从代码库推导的内容。</strong> grep 得到的、git 能查到的，不写。</li><li><strong><code>CLAUDE.md</code> 里已经写过的内容。</strong> 不重复记录。</li></ol><p>原因很直接：如果不去重，每次会话都在补重复信息，200 行的索引很快就会被塞满，然后开始截断，然后系统悄悄失效。</p><p><strong>索引能长期工作的前提，是写入端足够克制。</strong> 大多数自建记忆系统失败，不是败在检索算法，是败在没有这两条排除规则。</p><h2 id="五、子代理的隔离" tabindex="-1">五、子代理的隔离 <a class="header-anchor" href="#五、子代理的隔离" aria-label="Permalink to “五、子代理的隔离”">​</a></h2><p>主会话的 auto memory <strong>不会自动进入子代理</strong>。子代理可以用独立的 memory 目录。</p><p>这个设计暗示了一个判断：记忆是有作用域的，不是全局共享的。把所有记忆广播给所有子代理，等于让每个子代理都背上主会话的历史包袱。</p><h2 id="六、这套设计的取舍" tabindex="-1">六、这套设计的取舍 <a class="header-anchor" href="#六、这套设计的取舍" aria-label="Permalink to “六、这套设计的取舍”">​</a></h2><p>优点很清晰：</p><ul><li>启动成本固定在一个小索引上，不会随记忆总量增长。</li><li>细节按需读取，把固定成本换成按需成本。</li><li>有明确的时间戳和截断机制，不会无限膨胀。</li><li>写入端有减法，从源头上控制体量。</li></ul><p>代价也很清晰：</p><ul><li>索引被截断是静默的，你不容易发现记忆已经失效。</li><li>四类记忆（user/feedback/project/reference）的划分需要模型自己判断，判断错了就归错类。</li><li>它是上下文不是约束，指望它强制改变行为会失望。</li></ul><h2 id="不确定性与边界" tabindex="-1">不确定性与边界 <a class="header-anchor" href="#不确定性与边界" aria-label="Permalink to “不确定性与边界”">​</a></h2><ul><li>只采 Anthropic 官方 Claude Code 文档（memory、<code>.claude</code> 目录两页）。</li><li>社区流传的&quot;泄露源码分析&quot;未采信为结论，只作为不确定性提示。</li><li>四类记忆的具体划分标准、模型如何判断归类，官方文档未详细展开。</li><li>本文以 2026-11-09 访问的官方文档为准。</li></ul><hr>',40)),u("p",null,[e[3]||(e[3]=o("总览见 ",-1)),l(a,{href:"/nebula-blog/vault/Knowledge/AI/三大编码 Agent 都没有记忆库.html"},{default:t(()=>[...e[0]||(e[0]=[o("三大编码 Agent 都没有记忆库",-1)])]),_:1}),e[4]||(e[4]=o("，对照见 ",-1)),l(a,{href:"/nebula-blog/vault/Knowledge/AI/Codex 的记忆系统.html"},{default:t(()=>[...e[1]||(e[1]=[o("Codex 的记忆系统",-1)])]),_:1}),e[5]||(e[5]=o("、",-1)),l(a,{href:"/nebula-blog/vault/Knowledge/AI/Cursor 的记忆系统.html"},{default:t(()=>[...e[2]||(e[2]=[o("Cursor 的记忆系统",-1)])]),_:1}),e[6]||(e[6]=o("。",-1))]),l(r),l(n)])}const L=i(m,[["render",g]]);export{k as __pageData,L as default};
